import sys,os,collections,json
sys.path.insert(0,"/root/unitex-finrep/engine"); os.chdir("/root/unitex-finrep")
from odata_client import ODataClient
c=ODataClient()
vid={v["Ref_Key"]:(v.get("Description") or "").strip() for v in c.list("Catalog_ВидОплаты", select=["Ref_Key","Description"])}
cur={v["Ref_Key"]:(v.get("Description") or "").strip() for v in c.list("Catalog_Валюты", select=["Ref_Key","Description"])}
def n(x):
    try: return float(x or 0)
    except (TypeError,ValueError): return 0.0
def paid(v): return bool(str(v or "").startswith(("2","1")) and not str(v).startswith("0001"))
IN=collections.defaultdict(float); OUT=collections.defaultdict(float); CU={}
ni=no=0
for r in c.list("Document_Счет"):
    if str(r.get("СтатусСчета") or "")!="Оплачен": continue
    v=vid.get(r.get("видОплаты_Key"))
    if not v: continue
    IN[v]+=n(r.get("СуммаВал")); CU[v]=cur.get(r.get("Валюта_Key"),"?"); ni+=1
tot=0
for r in c.list("Catalog_СчетаПоставщиков"):
    tot+=1
    if not paid(r.get("ДатаОплаты")): continue
    v=vid.get(r.get("ВидОплаты_Key"))
    if not v: continue
    OUT[v]+=n(r.get("Сумма")); CU.setdefault(v,cur.get(r.get("Валюта_Key"),"?")); no+=1
print("оплачених доходних рахунків: %d | рахунків постачальників усього: %d, з них оплачених з видом оплати: %d"%(ni,tot,no),flush=True)
REPORT={"Банк Юнітекс Ейч-Ді":182939.49,"Банк Юнітекс Форвардинг":31929.73,"Банк Юнітекс Ейч-Ді Восток":11559.45,
 "Каса USD UFWD":26193.46,"Каса USD UHD":19662.91,"Банк Cr String Cycle LLC":3699.88,"Банк Юнітекс Ейч-Ді EUR":0.0,
 "Каса USD Украмарин":-5682.60,"Маерск USD":1935.38,"Депозити USD":8000.0,"Каса UAH UFWD":3909.52,"Каса UAH UHD":13958.77}
print("\n%-28s %4s %14s %14s %14s %13s"%("ВИД ОПЛАТИ","вал","надійшло","виплачено","різниця","твої залишки"))
res={}
for v in sorted(set(IN)|set(OUT)|set(REPORT)):
    i,o=IN.get(v,0.0),OUT.get(v,0.0); rep=REPORT.get(v)
    res[v]={"in":round(i,2),"out":round(o,2),"diff":round(i-o,2),"report":rep}
    print("%-28s %4s %14.2f %14.2f %14.2f %13s"%(v[:28],CU.get(v,"?"),i,o,i-o,("%.2f"%rep) if rep is not None else "—"))
json.dump(res,open("/root/direct-sync/cash_v3.json","w"),ensure_ascii=False,indent=1)
PY
cd /root/direct-sync && nohup /root/unitex-finrep/.venv/bin/python cash_v3.py > /root/direct-sync/cash_v3.out 2>&1 &
